    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case TimeSliderAction actions:
                Actions ??= [];
                if (!Actions.Contains(actions))
                {
                    Actions = [..Actions, actions];
                    ModifiedParameters[nameof(Actions)] = Actions;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case TimeSliderStops stops:
                if (stops != Stops)
                {
                    Stops = stops;
                    ModifiedParameters[nameof(Stops)] = Stops;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case TickConfig tickConfigs:
                TickConfigs ??= [];
                if (!TickConfigs.Contains(tickConfigs))
                {
                    TickConfigs = [..TickConfigs, tickConfigs];
                    ModifiedParameters[nameof(TickConfigs)] = TickConfigs;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case TimeSliderViewModel viewModel:
                if (viewModel != ViewModel)
                {
                    ViewModel = viewModel;
                    ModifiedParameters[nameof(ViewModel)] = ViewModel;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case TimeSliderAction actions:
                Actions = Actions?.Where(a => a != actions).ToList();
                ModifiedParameters[nameof(Actions)] = Actions;
                return true;
            case TimeSliderStops _:
                Stops = null;
                ModifiedParameters[nameof(Stops)] = Stops;
                return true;
            case TickConfig tickConfigs:
                TickConfigs = TickConfigs?.Where(t => t != tickConfigs).ToList();
                ModifiedParameters[nameof(TickConfigs)] = TickConfigs;
                return true;
            case TimeSliderViewModel _:
                ViewModel = null;
                ModifiedParameters[nameof(ViewModel)] = ViewModel;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        if (Actions is not null)
        {
            foreach (TimeSliderAction child in Actions)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        Stops?.ValidateRequiredGeneratedChildren();
        if (TickConfigs is not null)
        {
            foreach (TickConfig child in TickConfigs)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        ViewModel?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
